1	// Python int(str) parsing semantics, producing a BigInt.
2	// Rules: surrounding whitespace stripped, optional +/- sign, decimal digits,
3	// single underscores allowed between digits. Arbitrary precision via BigInt.
4	
5	export class PyIntError extends Error {
6	  constructor(value) {
7	    super(`invalid literal for int() with base 10: ${value}`);
8	    this.name = 'PyIntError';
9	    this.value = value;
10	  }
11	}
12	
13	export function parsePyInt(str) {
14	  // Python str.strip() removes leading/trailing whitespace.
15	  const stripped = str.replace(/^\s+|\s+$/g, '');
16	  const m = /^([+-]?)(\d(?:_?\d)*)$/.exec(stripped);
17	  if (!m) {
18	    throw new PyIntError(str);
19	  }
20	  const digits = m[2].replace(/_/g, '');
21	  // BigInt('-0') is 0n, matching Python int('-0') == 0.
22	  return BigInt((m[1] === '-' ? '-' : '') + digits);
23	}

1	// Bencode encode/decode over plain latin1 JS strings (no typed arrays).
2	// Value model: string = byte string, BigInt = integer, Array = list.
3	
4	export function encode(value) {
5	  if (typeof value === 'string') {
6	    return value.length + ':' + value;
7	  }
8	  if (typeof value === 'bigint') {
9	    return 'i' + value.toString() + 'e';
10	  }
11	  if (Array.isArray(value)) {
12	    return 'l' + value.map(encode).join('') + 'e';
13	  }
14	  throw new TypeError('bencode.encode: unsupported value type');
15	}
16	
17	export function decode(str) {
18	  let pos = 0;
19	
20	  function parse() {
21	    const c = str[pos];
22	    if (c === 'i') {
23	      const end = str.indexOf('e', pos);
24	      if (end === -1) throw new Error('bencode: unterminated integer');
25	      const n = BigInt(str.slice(pos + 1, end));
26	      pos = end + 1;
27	      return n;
28	    }
29	    if (c === 'l') {
30	      pos++;
31	      const items = [];
32	      while (str[pos] !== 'e') {
33	        if (pos >= str.length) throw new Error('bencode: unterminated list');
34	        items.push(parse());
35	      }
36	      pos++;
37	      return items;
38	    }
39	    if (c >= '0' && c <= '9') {
40	      const colon = str.indexOf(':', pos);
41	      if (colon === -1) throw new Error('bencode: missing colon');
42	      const len = parseInt(str.slice(pos, colon), 10);
43	      pos = colon + 1;
44	      if (pos + len > str.length) throw new Error('bencode: string overrun');
45	      const out = str.slice(pos, pos + len);
46	      pos += len;
47	      return out;
48	    }
49	    throw new Error('bencode: invalid token at position ' + pos);
50	  }
51	
52	  const value = parse();
53	  if (pos !== str.length) throw new Error('bencode: trailing data');
54	  return value;
55	}

