15	// Python repr() of a str (used by argparse for invalid int values):
16	// single quotes by default, double quotes if the string contains ' but not ".
17	export function pyStrRepr(s) {
18	  const hasSingle = s.indexOf("'") !== -1;
19	  const hasDouble = s.indexOf('"') !== -1;
20	  const quote = hasSingle && !hasDouble ? '"' : "'";
21	  let out = quote;
22	  for (let i = 0; i < s.length; i++) {
23	    const ch = s[i];
24	    const code = s.charCodeAt(i);
25	    if (ch === '\\') out += '\\\\';
26	    else if (ch === quote) out += '\\' + quote;
27	    else if (ch === '\n') out += '\\n';
28	    else if (ch === '\r') out += '\\r';
29	    else if (ch === '\t') out += '\\t';
30	    else if (code >= 0x20 && code <= 0x7e) out += ch;
31	    else if (code <= 0xff) out += '\\x' + code.toString(16).padStart(2, '0');
32	    else if (code <= 0xffff) out += '\\u' + code.toString(16).padStart(4, '0');
33	    else out += '\\U' + code.toString(16).padStart(8, '0');
