6	export class AsciiEncodeError extends Error {
7	  constructor(ch, position, code) {
8	    super('UnicodeEncodeError');
9	    this.name = 'AsciiEncodeError';
10	    this.ch = ch;
11	    this.position = position;
12	    this.code = code;
13	  }
