17	  for (let i = 0; i < str.length; i++) {
18	    const code = str.charCodeAt(i);
19	    if (code > 127) {
20	      throw new AsciiEncodeError(str[i], i, code);
21	    }
22	  }
23	  // All codes <= 127, so the string is already valid latin1 "bytes".
24	  return str;
